        const float Duration=.14f/3;readonly Transform root,model,trailRoot,guard,cue;readonly Mesh trailMesh;readonly MeshRenderer trailRenderer;readonly List<UnityEngine.Object> owned=new List<UnityEngine.Object>();readonly List<Stamp> history=new List<Stamp>();readonly List<Vector3> vertices=new List<Vector3>();readonly List<Color> colors=new List<Color>();readonly List<int> indices=new List<int>();readonly string profile;Vector3 previousLocalBase,previousLocalTip;bool trailMotionReady;
        public bool GuardVisible{get{return guard.gameObject.activeInHierarchy;}}public bool TrailVisible{get{return trailRenderer.enabled;}}
        public R24BladeArt(string id,Transform sourceModel,Mesh sourceCueMesh){profile=id;model=sourceModel;root=Node("Source melee transient art",model);root.gameObject.layer=18;var colorShader=Resources.Load<Shader>("R23GunFeedback");var ribbonShader=Resources.Load<Shader>("R24ReviveArcs");var shieldShader=Resources.Load<Shader>("R24KatanaGuard");if(colorShader==null||ribbonShader==null||shieldShader==null)throw new InvalidOperationException("Source melee shaders missing");
            guard=Node("Actual source finite katana shield",root);guard.localPosition=new Vector3(0,.34f,.08f);var shieldMesh=Quad(R24MeleeRuntime.ShieldHalfWidth,R24MeleeRuntime.ShieldHalfHeight);owned.Add(shieldMesh);var shieldMaterial=new Material(shieldShader);owned.Add(shieldMaterial);Part("original angular pane",guard,shieldMesh,shieldMaterial);
            var edge=new Material(colorShader);owned.Add(edge);edge.SetColor("_Color",new Color(.141f,.973f,.357f));edge.SetFloat("_Cull",0);var cube=Cube();owned.Add(cube);for(int side=-1;side<=1;side+=2){var vertical=Part("source shield vertical edge",guard,cube,edge);vertical.localPosition=new Vector3(side*R24MeleeRuntime.ShieldHalfWidth,0,-.001f);vertical.localScale=new Vector3(.008f,R24MeleeRuntime.ShieldHalfHeight*2,.005f);var horizontal=Part("source shield horizontal edge",guard,cube,edge);horizontal.localPosition=new Vector3(0,side*R24MeleeRuntime.ShieldHalfHeight,-.001f);horizontal.localScale=new Vector3(R24MeleeRuntime.ShieldHalfWidth*2,.008f,.005f);}
            var cyan=new Material(colorShader);owned.Add(cyan);cyan.SetColor("_Color",new Color(.322f,.788f,.851f));cue=Part("Source hilt support cue",root,sourceCueMesh,cyan);cue.localPosition=new Vector3(0,-.190f,-.025f);guard.gameObject.SetActive(false);cue.gameObject.SetActive(false);
            trailRoot=new GameObject("Source short world blade ribbon").transform;trailRoot.gameObject.layer=0;trailMesh=new Mesh();trailMesh.MarkDynamic();owned.Add(trailMesh);trailRoot.gameObject.AddComponent<MeshFilter>().sharedMesh=trailMesh;trailRenderer=trailRoot.gameObject.AddComponent<MeshRenderer>();var trailMaterial=new Material(ribbonShader);owned.Add(trailMaterial);trailRenderer.sharedMaterial=trailMaterial;trailRenderer.shadowCastingMode=ShadowCastingMode.Off;trailRenderer.receiveShadows=false;trailRenderer.enabled=false;
        }
