        public void SampleBlade(Vector3 lower,Vector3 tip,float seconds,bool enabled,Transform actor){var a=actor.InverseTransformPoint(lower);var b=actor.InverseTransformPoint(tip);bool moving=trailMotionReady&&seconds>0&&Mathf.Max(Vector3.Distance(a,previousLocalBase),Vector3.Distance(b,previousLocalTip))/Mathf.Max(seconds,.0001f)>.5f;previousLocalBase=a;previousLocalTip=b;trailMotionReady=enabled;SampleTrail(lower,tip,seconds,enabled&&moving);}
